sandbox.inicial:
let atual = '0', anterior = null, operacao = null;

teclado.addEventListener('click', (e) => {
  const b = e.target;
  if (b.dataset.valor) digitar(b.dataset.valor);
  else if (b.dataset.acao) acao(b.dataset.acao);
});

function digitar(d) {
  if (d === '.' && atual.includes('.')) return;   // um ponto só
  atual = (atual === '0' && d !== '.') ? d : atual + d;
}
function operar(op) {
  anterior = atual; operacao = op; atual = '0';   // guarda e espera
}
function igual() {
  const a = Number(anterior), b = Number(atual);
  atual = String(operacao === '+' ? a + b : operacao === '-' ? a - b : operacao === '*' ? a * b : a / b);
  operacao = null;
}

function dividir(a, b) {
  if (b === 0) return 'não dá';          // trata a divisão por zero
  return Math.round((a / b) * 1e10) / 1e10;  // esconde o ruído do ponto flutuante
}
function limpar() {
  atual = '0'; anterior = null; operacao = null;
}
